#include "log.h"
#include "store/ring.h"

#define SPI_DEV			"/dev/spidev0.0"
#define SPI_SPEED_HZ		1000000u	/* MCP3008 max is 1.35 MHz at 3.3 V */
#define SPI_BITS		8
#define MCP3008_CHANNEL		0
#define RAIL_LOW_MAX		5
