}

/* Reap a dead child and schedule its re-fork. Returns -1 on fatal error. */
static int on_sigchld(struct child_sup *cs, int restart_fd)
{
	char why[32];
	unsigned long n;
	long secs;
	time_t now;
	int status;
	pid_t dead = cs->pid, r;

	if (dead <= 0)
